// Search queries for series (episode 1 of each)
const queries = [
  { query: 'مسلسل تركي مدبلج بالعربية الحلقة الأولى',   origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'مسلسل هندي مدبلج بالعربية الحلقة الأولى',   origin: 'indian',   language: 'ar_dubbed' },
  { query: 'مسلسل كوري مدبلج بالعربية الحلقة 1',        origin: 'korean',   language: 'ar_dubbed' },
  { query: 'مسلسل مغربي بالدارجة الحلقة الأولى',         origin: 'moroccan', language: 'darija'    },
  { query: 'مسلسل تركي مدبلج 2024 حلقة 1',              origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'مسلسل هندي دراما مدبلج عربي الحلقة الأولى', origin: 'indian',   language: 'ar_dubbed' }
];
return queries.map(q => ({ json: q }));

// For series discovery, we detect pilot episodes and create series metadata
const results = $input.first().json.results || [];
const query = $('Generate Series Queries').item.json;

// Try to extract series name from episode title
function extractSeriesName(title) {
  // Remove episode indicators
  return title
    .replace(/الحلقة\s*\d+/g, '')
    .replace(/حلقة\s*\d+/g, '')
    .replace(/episode\s*\d+/gi, '')
    .replace(/ep\.?\s*\d+/gi, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

const series = results
  .filter(r => r.embeddable !== false)
  .map(r => ({
    ytId:      r.ytId,
    title_ar:  extractSeriesName(r.title_ar || r.title),
    title_orig: r.title,
    origin:    r.origin !== 'other' ? r.origin : query.origin,
    language:  r.language !== 'ar_dubbed' ? r.language : query.language,
    category:  r.category,
    poster_url: r.poster_url,
    year:      r.year,
    // For series: create a series ID based on cleaned title
    series_id: 'series_' + (extractSeriesName(r.title_ar || r.title).slice(0,30).replace(/\s+/g,'_').replace(/[^\w]/g,'') || r.ytId),
    episode_yt_id: r.ytId,
    query: query.query
  }));

console.log(`Series query: ${query.query} → ${series.length} results`);
return [{ json: { series, query: query.query } }];

// Import each series metadata + first episode
const { series } = $input.first().json;
const API_URL = 'https://mawso3a-stream.vercel.app/api/import';
const SECRET = 'wxoS5Xnuqi6IJra8IEodigDALy4XdWdTfsTz6R9JhOM=';

async function post(action, body) {
  const r = await fetch(`${API_URL}?action=${action}`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${SECRET}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return r.json();
}

let imported = 0, skipped = 0;
for (const s of series) {
  // Create series entry
  const sr = await post('import-series', {
    id: s.series_id, title_ar: s.title_ar, title_orig: s.title_orig,
    origin: s.origin, language: s.language, category: s.category,
    poster_url: s.poster_url, year: s.year, total_eps: 0
  });

  // Import first episode
  const er = await post('import-episode', {
    ytId: s.episode_yt_id, series_id: s.series_id,
    title_ar: s.title_orig, season: 1, episode: 1
  });

  er.ok ? imported++ : skipped++;
}

console.log(`✅ Series auto-discovery: ${imported} imported, ${skipped} skipped`);
return [{ json: { imported, skipped, run_at: new Date().toISOString() } }];
